edits.oldText:
/// Search the MusicBrainz artist index for the artist claiming a code.
///
/// A provider that cannot search by code reports it instead of returning
/// nothing: an empty result would be indistinguishable from a code no artist
/// carries. The production provider and the test doubles implement it.
async fn search_artists_by_code(
    &self,
    code: CodeIdentifier<'_>,
) -> std::result::Result<Vec<ArtistCandidate>, DiscographyError> {
    Err(DiscographyError::ArtistSearchInconsistent(format!(
        "{} {} search is not supported by this provider",
        code.kind(),
        code.value()
    )))
}

