pub fn pin_key(key: &str) -> String {
    let trimmed = key.trim();
    let Some((prefix, rest)) = trimmed.split_once(':') else {
        return normalize_catalog_key(trimmed);
    };
    let value: String = rest
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-')
        .collect();
    match prefix.trim().to_ascii_lowercase().as_str() {
        "isni" => format!("isni:{}", value.to_ascii_uppercase()),
        "ipi" => format!("ipi:{value}"),
        "mbid" => format!("mbid:{}", value.to_ascii_lowercase()),
        // Any other colon-bearing key is a name, folded as before.
        _ => normalize_catalog_key(trimmed),
    }
}

